      "html": "<div style='font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto; padding: 20px; background: #0d1117; color: #c9d1d9; border-radius: 12px;'><h2 style='text-align: center; color: #58a6ff;'>📐 Pascal's Triangle as Ramsey Exponents</h2><p style='text-align: center; color: #8b949e; font-size: 13px;'>C(k,r) is the exponent in R_r(k,k) ≥ 2^{C(k,r)/k}. Hover over entries to see the Ramsey interpretation.</p><div style='display: flex; gap: 15px; margin: 15px 0; justify-content: center;'><label style='color: #58a6ff;'>Max row: <span id='maxrow'>10</span></label><input type='range' id='rowslider' min='4' max='15' value='10' style='width: 200px;' oninput='drawPascal()'><label style='margin-left: 15px; color: #58a6ff;'>Highlight r: <span id='hr'>3</span></label><input type='range' id='hslider' min='1' max='7' value='3' style='width: 150px;' oninput='drawPascal()'></div><div id='pascal' style='text-align: center; padding: 10px;'></div><div id='tooltip' style='background: #21262d; padding: 10px; border-radius: 6px; margin-top: 10px; min-height: 40px; border: 1px solid #30363d;'><span style='color: #8b949e;'>Hover over a number to see its Ramsey theory interpretation</span></div><script>function choose(n, r) { if (r > n || r < 0) return 0; if (r === 0 || r === n) return 1; let result = 1; for (let i = 0; i < r; i++) result = result * (n - i) / (i + 1); return Math.round(result); } function drawPascal() { let maxK = parseInt(document.getElementById('rowslider').value); let highlightR = parseInt(document.getElementById('hslider').value); document.getElementById('maxrow').textContent = maxK; document.getElementById('hr').textContent = highlightR; let html = ''; for (let k = 0; k <= maxK; k++) { html += '<div style=\"margin: 2px 0;\">'; for (let r = 0; r <= k; r++) { let val = choose(k, r); let isHighlight = r === highlightR; let isEdge = r === 0 || r === k; let bg = isHighlight ? '#1f6feb' : isEdge ? '#21262d' : '#161b22'; let border = isHighlight ? '2px solid #58a6ff' : '1px solid #30363d'; let color = isHighlight ? '#fff' : '#c9d1d9'; let fontSize = val > 999 ? '9px' : val > 99 ? '10px' : '12px'; html += '<span style=\"display: inline-block; width: 42px; height: 28px; line-height: 28px; margin: 1px; background: ' + bg + '; border: ' + border + '; border-radius: 4px; font-size: ' + fontSize + '; color: ' + color + '; cursor: pointer; text-align: center;\" onmouseover=\"showInfo(' + k + ',' + r + ',' + val + ')\">' + val + '</span>'; } html += '</div>'; } document.getElementById('pascal').innerHTML = html; } function showInfo(k, r, val) { let tooltip = document.getElementById('tooltip'); if (r < 2 || r > k) { tooltip.innerHTML = '<span style=\"color: #58a6ff;\">C(' + k + ',' + r + ') = ' + val + '</span> — trivial case (r < 2 or r = k)'; return; } let lowerBound = Math.pow(2, val / k); let lbStr = lowerBound > 1e15 ? '2^{' + (val/k).toFixed(1) + '}' : Math.round(lowerBound).toLocaleString(); tooltip.innerHTML = '<span style=\"color: #58a6ff; font-weight: bold;\">C(' + k + ',' + r + ') = ' + val + '</span><br>' + '<span style=\"color: #3fb950;\">R_' + r + '(' + k + ',' + k + ') ≥ 2^{' + val + '/' + k + '} ≈ ' + lbStr + '</span><br>' + '<span style=\"color: #8b949e;\">The ' + r + '-uniform hypergraph Ramsey number for clique size ' + k + ' is at least exponential with exponent proportional to ' + val + '.</span>'; } drawPascal();</script></div>"
