t('div');d2.className='cell cell-w'+(v[i]===w[i]?' cell-match':' cell-diff');d2.textContent=w[i];d2.onclick=()=>{w[i]=(w[i]+1)%A;render()};cW.appendChild(d2)}let dist=0;for(let i=0;i<L;i++)if(v[i]!==w[i])dist++;document.getElementById('distVal').textContent=dist;document.getElementById('maxVal').textContent=L;document.getElementById('degVal').textContent=L*(A-1);const ls=Math.pow(A,L);document.getElementById('libVal').textContent=ls>1e9?A+'^'+L:ls.toLocaleString();document.getElementById('distBar').style.width=(dist/L*100)+'%'}document.getElementById('selA').onchange=init;document.getElementById('selL').onchange=init;document.getElementById('btnRand').onclick=()=>{for(let i=0;i<L;i++){v[i]=Math.floor(Math.random()*A);w[i]=Math.floor(Math.random()*A)}render()};init()</script></body></html>"
