.height,pad=60;ctx.clearRect(0,0,W,H);ctx.fillStyle='#0f0f24';ctx.fillRect(0,0,W,H);const data=[];for(let d=1;d<=L;d++){data.push({d,logBound:(L-d+1)*Math.log10(A)})}const maxLog=data[0].logBound;ctx.strokeStyle='#333';ctx.lineWidth=1;ctx.beginPath();for(let i=0;i<=5;i++){const y=pad+(H-2*pad)*(i/5);ctx.moveTo(pad,y);ctx.lineTo(W-pad,y);const val=(maxLog*(1-i/5)).toFixed(1);ctx.fillStyle='#666';ctx.font='11px monospace';ctx.textAlign='right';ctx.fillText(val,pad-8,y+4)}ctx.stroke();ctx.fillStyle='#888';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.save();ctx.translate(15,(H)/2);ctx.rotate(-Math.PI/2);ctx.fillText('log₁₀(Singleton Bound)',0,0);ctx.restore();ctx.fillText('Minimum Distance d',W/2,H-8);for(let i=0;i<data.length;i+=Math.max(1,Math.floor(data.length/10))){const x=pad+(W-2*pad)*(i/(data.length-1));ctx.fillStyle='#666';ctx.font='11px monospace';ctx.fillText(data[i].d,x,H-pad+18)}ctx.beginPath();ctx.strokeStyle='#f0c040';ctx.lineWidth=2.5;data.forEach((pt,i)=>{const x=pad+(W-2*pad)*(i/(data.length-1));const y=pad+(H-2*pad)*(1-pt.logBound/maxLog);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke();ctx.fillStyle='rgba(240,192,64,0.08)';ctx.beginPath();data.forEach((pt,i)=>{const x=pad+(W-2*pad)*(i/(data.length-1));const y=pad+(H-2*pad)*(1-pt.logBound/maxLog);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.lineTo(W-pad,H-pad);ctx.lineTo(pad,H-pad);ctx.closePath();ctx.fill();const midD=Math.floor(L/2);const midBound=Math.pow(A,L-midD+1);document.getElementById('highlight').textContent=`At d=${midD}, Singleton allows ≤ ${A}^${L-midD+1} = ${midBound>1e15?A+'^'+(L-midD+1):midBound.toLocaleString()} codewords out of ${Math.pow(A,L)>1e15?A+'^'+L:Math.pow(A,L).toLocaleString()} total volumes.`}document.getElementById('inA').oninput=draw;document.getElementById('inL').oninput=draw;draw()</script></body></html>"
