      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Voice Swap</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:20px}h1{color:#8af;margin-bottom:4px}h2{color:#888;font-weight:normal;font-size:1em;margin-bottom:20px}canvas{border-radius:12px;background:#111;box-shadow:0 0 30px rgba(100,150,255,0.1)}.explanation{max-width:650px;margin-top:16px;background:#1a1a2e;padding:16px 24px;border-radius:8px;font-size:0.95em;line-height:1.6;text-align:center}</style></head><body><h1>Voice-Swap Asymmetry</h1><h2>The involution i ↦ −i (mod 12) on the chromatic circle</h2><canvas id='c' width='650' height='650'></canvas><div class='explanation'>The <b style='color:#ff6b6b'>red arc</b> (7 → 5) shows the broken symmetry: the <b>perfect fifth</b> maps to the <b>perfect fourth</b>, which is <em>not</em> consonant in first-species counterpoint. This formalizes the privileged role of the bass voice.</div><script>const C=document.getElementById('c'),ctx=C.getContext('2d'),W=650,H=650,cx=W/2,cy=H/2,R=250;const names=['P1/P8','m2','M2','m3','M3','P4','TT','P5','m6','M6','m7','M7'];const consonant=new Set([0,3,4,7,8,9]);const pairs=[];for(let i of consonant){let neg=(12-i)%12;pairs.push({from:i,to:neg,preserved:consonant.has(neg)})}function angle(i){return-Math.PI/2+i*2*Math.PI/12}function draw(){ctx.clearRect(0,0,W,H);ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.strokeStyle='#333';ctx.lineWidth=2;ctx.stroke();for(let i=0;i<12;i++){let a=angle(i),x=cx+R*Math.cos(a),y=cy+R*Math.sin(a);let isCon=consonant.has(i);ctx.beginPath();ctx.arc(x,y,isCon?18:10,0,Math.PI*2);if(isCon){let isPerfect=[0,7].includes(i);ctx.fillStyle=isPerfect?'#ff6b6b':'#4ecdc4';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke()}else{ctx.fillStyle='#333';ctx.fill();ctx.strokeStyle='#555';ctx.lineWidth=1;ctx.stroke()}ctx.fillStyle=isCon?'#fff':'#777';ctx.font=isCon?'bold 11px sans-serif':'10px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(i,x,y);ctx.fillStyle=isCon?'#ccc':'#555';ctx.font='10px sans-serif';let lx=cx+(R+35)*Math.cos(a),ly=cy+(R+35)*Math.sin(a);ctx.fillText(names[i],lx,ly)}pairs.forEach(p=>{if(p.from===p.to)return;let a1=angle(p.from),a2=angle(p.to);let x1=cx+R*Math.cos(a1),y1=cy+R*Math.sin(a1);let x2=cx+R*Math.cos(a2),y2=cy+R*Math.sin(a2);let mx=(x1+x2)/2,my=(y1+y2)/2;let dx=mx-cx,dy=my-cy,dl=Math.sqrt(dx*dx+dy*dy)||1;let curve=p.preserved?0.3:0.4;let cpx=mx-dx*curve,cpy=my-dy*curve;ctx.beginPath();ctx.moveTo(x1,y1);ctx.quadraticCurveTo(cpx,cpy,x2,y2);ctx.strokeStyle=p.preserved?'rgba(78,205,196,0.6)':'rgba(255,107,107,0.8)';ctx.lineWidth=p.preserved?2:3;ctx.setLineDash(p.preserved?[]:[8,4]);ctx.stroke();ctx.setLineDash([]);let t=0.6,bx=(1-t)*(1-t)*x1+2*(1-t)*t*cpx+t*t*x2,by=(1-t)*(1-t)*y1+2*(1-t)*t*cpy+t*t*y2;let t2=0.61,bx2=(1-t2)*(1-t2)*x1+2*(1-t2)*t2*cpx+t2*t2*x2,by2=(1-t2)*(1-t2)*y1+2*(1-t2)*t2*cpy+t2*t2*y2;let adx=bx2-bx,ady=by2-by,al=Math.sqrt(adx*adx+ady*ady)||1;adx/=al;ady/=al;ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(bx-adx*10-ady*5,by-ady*10+adx*5);ctx.lineTo(bx-adx*10+ady*5,by-ady*10-adx*5);ctx.closePath();ctx.fillStyle=p.preserved?'rgba(78,205,196,0.6)':'rgba(255,107,107,0.8)';ctx.fill();let lbl=p.preserved?'✓':'✗ ('+p.to+' not consonant)';if(!p.preserved){ctx.font='bold 11px sans-serif';ctx.fillStyle='#ff6b6b';ctx.textAlign='center';let lmx=(x1+x2)/2-dx*curve*0.5-20,lmy=(y1+y2)/2-dy*curve*0.5;ctx.fillText(p.from+'→'+p.to+' ✗',lmx,lmy)}});ctx.fillStyle='#555';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText('i ↦ −i (mod 12)',cx,cy-10);ctx.fillText('Voice Swap Involution',cx,cy+10)}draw()</script></body></html>"
