      "html": "<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1.0'><title>Library Explorer</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;min-height:100vh;display:flex;flex-direction:column;align-items:center;padding:20px}.container{max-width:900px;width:100%}h1{text-align:center;color:#7eb8da;margin-bottom:5px;font-size:1.6em}h2{text-align:center;color:#5a9;font-size:1em;margin-bottom:20px;font-weight:normal}.controls{display:flex;gap:15px;margin-bottom:20px;flex-wrap:wrap;justify-content:center}.controls label{display:flex;align-items:center;gap:6px;font-size:.9em}.controls input,.controls select{background:#1a1a2e;border:1px solid #333;color:#e0e0e0;padding:5px 10px;border-radius:4px;font-size:.9em}.volume-display{background:#111;border:1px solid #333;border-radius:8px;padding:15px;margin-bottom:15px}.volume-display h3{color:#7eb8da;margin-bottom:8px;font-size:1em}.vol-string{font-family:'Fira Code',monospace;font-size:1.1em;letter-spacing:2px;color:#f0c040;word-break:break-all}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-bottom:20px}.stat-card{background:#111;border:1px solid #333;border-radius:8px;padding:12px;text-align:center}.stat-card .value{font-size:1.8em;color:#7eb8da;font-weight:bold}.stat-card .label{font-size:.8em;color:#888;margin-top:4px}.neighbors{background:#111;border:1px solid #333;border-radius:8px;padding:15px;max-height:400px;overflow-y:auto}.neighbors h3{color:#5a9;margin-bottom:10px}.neighbor-item{font-family:'Fira Code',monospace;font-size:.85em;padding:4px 8px;margin:2px 0;border-radius:4px;cursor:pointer;transition:background .2s}.neighbor-item:hover{background:#1a2a3a}.neighbor-item .pos{color:#f66;font-weight:bold}.neighbor-item .dist-badge{float:right;background:#234;padding:1px 8px;border-radius:10px;font-size:.8em;color:#7eb8da}.btn{background:#234;border:1px solid #456;color:#7eb8da;padding:6px 16px;border-radius:4px;cursor:pointer;font-size:.9em;transition:background .2s}.btn:hover{background:#345}</style></head><body><div class='container'><h1>📚 Library of Babel Explorer</h1><h2>Degree Regularity & Hamming Distance</h2><div class='controls'><label>Alphabet (A): <select id='alphaSize'><option value='2'>2</option><option value='3'>3</option><option value='4' selected>4</option><option value='5'>5</option></select></label><label>Length (L): <input type='number' id='bookLen' value='8' min='1' max='20' style='width:60px'></label><button class='btn' onclick='randomVolume()'>🎲 Random Volume</button><button class='btn' onclick='zeroVolume()'>0⃣ Zero Volume</button></div><div class='stats'><div class='stat-card'><div class='value' id='totalVols'>—</div><div class='label'>Total Volumes (A^L)</div></div><div class='stat-card'><div class='value' id='degreeVal'>—</div><div class='label'>Neighbors (L×(A−1))</div></div><div class='stat-card'><div class='value' id='diameterVal'>—</div><div class='label'>Diameter (L)</div></div><div class='stat-card'><div class='value' id='singletonVal'>—</div><div class='label'>Singleton (d=2)</div></div></div><div class='volume-display'><h3>Current Volume</h3><div class='vol-string' id='currentVol'>Click a button to start</div></div><div class='neighbors'><h3>Hamming Neighbors (distance = 1) — <span id='neighCount'>0</span> total</h3><div id='neighList'></div></div></div><script>let A=4,L=8,currentV=[];function getA(){return parseInt(document.getElementById('alphaSize').value)}function getL(){return parseInt(document.getElementById('bookLen').value)}function hammingDist(a,b){let d=0;for(let i=0;i<a.length;i++)if(a[i]!==b[i])d++;return d}function updateStats(){A=getA();L=getL();const total=Math.pow(A,L);document.getElementById('totalVols').textContent=total>1e12?A+'^'+L:total.toLocaleString();document.getElementById('degreeVal').textContent=(L*(A-1)).toLocaleString();document.getElementById('diameterVal').textContent=L;const sb=Math.pow(A,L-1);document.getElementById('singletonVal').textContent=sb>1e12?A+'^'+(L-1):sb.toLocaleString()}function setVolume(v){currentV=[...v];document.getElementById('currentVol').textContent=v.join('');showNeighbors()}function randomVolume(){A=getA();L=getL();const v=[];for(let i=0;i<L;i++)v.push(Math.floor(Math.random()*A));updateStats();setVolume(v)}function zeroVolume(){A=getA();L=getL();updateStats();setVolume(Array(L).fill(0))}function showNeighbors(){const list=document.getElementById('neighList');list.innerHTML='';const neighbors=[];for(let i=0;i<L;i++){for(let a=0;a<A;a++){if(a!==currentV[i]){const w=[...currentV];w[i]=a;neighbors.push({vol:w,pos:i,oldVal:currentV[i],newVal:a})}}}document.getElementById('neighCount').textContent=neighbors.length;const shown=Math.min(neighbors.length,200);for(let n=0;n<shown;n++){const nb=neighbors[n];const div=document.createElement('div');div.className='neighbor-item';let html='';for(let i=0;i<nb.vol.length;i++){if(i===nb.pos)html+='<span class=\"pos\">'+nb.vol[i]+'</span>';else html+=nb.vol[i]}html+='<span class=\"dist-badge\">pos '+nb.pos+': '+nb.oldVal+'→'+nb.newVal+'</span>';div.innerHTML=html;div.onclick=()=>setVolume(nb.vol);list.appendChild(div)}if(neighbors.length>shown){const more=document.createElement('div');more.style.cssText='text-align:center;padding:10px;color:#666';more.textContent='... and '+(neighbors.length-shown)+' more neighbors';list.appendChild(more)}}document.getElementById('alphaSize').onchange=updateStats;document.getElementById('bookLen').onchange=updateStats;randomVolume()</script></body></html>"
