const logBound=exp*logA;const pct=Math.pow(10,logBound-maxLog)*100;const tr=document.createElement('tr');tr.innerHTML='<td>'+d+'</td><td>'+exp+'</td><td>'+A+'<sup>'+exp+'</sup></td><td>'+logBound.toFixed(1)+'</td><td>'+(pct>0.01?pct.toExponential(2):pct.toExponential(2))+'</td>';tb.appendChild(tr)})}document.getElementById('sA').oninput=update;document.getElementById('sL').oninput=update;update()</script></body></html>"
