);row.className='bar-row';const w=distCount[d]/maxC*100;row.innerHTML='<div class=\"bar-label\">d='+d+'</div><div class=\"bar\" style=\"width:'+w+'%;background:'+color(d,L)+'\"></div><div class=\"bar-val\">'+distCount[d]+' pairs</div>';hist.appendChild(row)}canvas.onmousemove=function(e){const rect=canvas.getBoundingClientRect();const x=Math.floor((e.clientX-rect.left)/cell);const y=Math.floor((e.clientY-rect.top)/cell);if(x>=0&&x<n&&y>=0&&y<n){const d=hDist(volumes[y],volumes[x]);document.getElementById('hoverInfo').innerHTML='<span>Volume '+y+':</span> ['+volumes[y].join('')+'] <span>↔</span> <span>Volume '+x+':</span> ['+volumes[x].join('')+'] <span>Distance: '+d+'</span>'}};canvas.onmouseleave=function(){document.getElementById('hoverInfo').innerHTML='Hover over the heatmap to see distances'}}document.getElementById('hA').onchange=draw;document.getElementById('hL').onchange=draw;draw()</script></body></html>"
