      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Counterpoint Quiver</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}.title{font-size:1.5rem;font-weight:300;letter-spacing:2px;margin-bottom:8px;color:#88aaff}.subtitle{font-size:.85rem;color:#666;margin-bottom:20px}.container{position:relative;width:600px;height:600px}canvas{border-radius:12px;background:#0d0d24;box-shadow:0 0 40px rgba(50,80,180,.15)}.info{position:absolute;top:15px;right:15px;background:rgba(10,10,30,.9);border:1px solid #334;border-radius:8px;padding:12px 16px;font-size:.8rem;line-height:1.6;max-width:200px}.legend{display:flex;gap:20px;margin-top:16px;font-size:.8rem}.legend-item{display:flex;align-items:center;gap:6px}.dot{width:12px;height:12px;border-radius:50%}.stats{margin-top:16px;font-size:.8rem;color:#888;text-align:center;line-height:1.8}</style></head><body><div class=\"title\">THE COUNTERPOINT QUIVER</div><div class=\"subtitle\">Q(C₁₂, P₁₂) — First-Species Voice Leadings over ℤ/12ℤ</div><div class=\"container\"><canvas id=\"c\" width=\"600\" height=\"600\"></canvas><div class=\"info\" id=\"info\">Click a node to inspect its voice-leading connections.</div></div><div class=\"legend\"><div class=\"legend-item\"><div class=\"dot\" style=\"background:#ff6b6b\"></div>Perfect consonance</div><div class=\"legend-item\"><div class=\"dot\" style=\"background:#4ecdc4\"></div>Imperfect consonance</div></div><div class=\"stats\" id=\"stats\"></div><script>const C=[0,3,4,7,8,9],P=new Set([0,7]),N=12;const names={0:'Unison',3:'min 3rd',4:'Maj 3rd',7:'P5th',8:'min 6th',9:'Maj 6th'};function targetInt(s,b,sp){return((s+sp-b)%N+N)%N}function isPar(b,s){return b===s&&b%N!==0}function isPermitted(src,tgt,b,s){return C.includes(src)&&C.includes(tgt)&&targetInt(src,b,s)===tgt&&!(P.has(tgt)&&isPar(b,s))}const edges={};let totalEdges=0;C.forEach(i=>{C.forEach(j=>{let cnt=0;for(let b=0;b<N;b++)for(let s=0;s<N;s++)if(isPermitted(i,j,b,s))cnt++;edges[i+','+j]=cnt;totalEdges+=cnt})});const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');const cx=300,cy=300,R=200;const positions={};C.forEach((v,idx)=>{const a=-Math.PI/2+idx*2*Math.PI/6;positions[v]={x:cx+R*Math.cos(a),y:cy+R*Math.sin(a)}});let selected=null;function draw(){ctx.clearRect(0,0,600,600);C.forEach(i=>{C.forEach(j=>{if(i===j)return;const cnt=edges[i+','+j];if(!cnt)return;const p1=positions[i],p2=positions[j];const dx=p2.x-p1.x,dy=p2.y-p1.y;const len=Math.sqrt(dx*dx+dy*dy);const nx=-dy/len,ny=dx/len;const off=3;const mx=(p1.x+p2.x)/2+nx*off*2,my=(p1.y+p2.y)/2+ny*off*2;let alpha=.08+cnt/72*.15;let width=.5+cnt/12;let color='rgba(100,140,255,';if(selected!==null){if(selected===i){alpha=.6;width=1.5+cnt/8;color='rgba(255,200,100,'}else if(selected===j){alpha=.6;width=1.5+cnt/8;color='rgba(100,255,200,'}else{alpha=.03;width=.3}}ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.quadraticCurveTo(mx,my,p2.x,p2.y);ctx.strokeStyle=color+alpha+')';ctx.lineWidth=width;ctx.stroke();if(alpha>.1){const t=.7;const ax=(1-t)*((1-t)*p1.x+t*mx)+t*((1-t)*mx+t*p2.x);const ay=(1-t)*((1-t)*p1.y+t*my)+t*((1-t)*my+t*p2.y);const adx=2*(1-t)*(mx-p1.x)+2*t*(p2.x-mx);const ady=2*(1-t)*(my-p1.y)+2*t*(p2.y-my);const al=Math.sqrt(adx*adx+ady*ady);const ux=adx/al,uy=ady/al;const sz=5;ctx.beginPath();ctx.moveTo(ax,ay);ctx.lineTo(ax-sz*ux+sz*.4*(-uy),ay-sz*uy+sz*.4*ux);ctx.lineTo(ax-sz*ux-sz*.4*(-uy),ay-sz*uy-sz*.4*ux);ctx.fillStyle=color+Math.min(alpha*2,.8)+')';ctx.fill()}})});C.forEach(v=>{const p=positions[v];const isPerfect=P.has(v);const selfLoops=edges[v+','+v];const r=isPerfect?18:24;const glowR=r+selfLoops;if(selected===v){ctx.beginPath();ctx.arc(p.x,p.y,glowR+10,0,Math.PI*2);ctx.fillStyle='rgba(255,255,255,.06)';ctx.fill()}ctx.beginPath();ctx.arc(p.x,p.y,glowR,0,Math.PI*2);ctx.fillStyle=isPerfect?'rgba(255,107,107,.1)':'rgba(78,205,196,.1)';ctx.fill();ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle=isPerfect?'#ff6b6b':'#4ecdc4';if(selected===v)ctx.fillStyle=isPerfect?'#ff9b9b':'#7eeee7';ctx.fill();ctx.strokeStyle=selected===v?'#fff':'rgba(255,255,255,.3)';ctx.lineWidth=selected===v?2:1;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(names[v],p.x,p.y);ctx.font='9px system-ui';ctx.fillStyle='#aaa';ctx.fillText(selfLoops+' loops',p.x,p.y+r+14)});const info=document.getElementById('info');if(selected!==null){const v=selected;const isPerfect=P.has(v);let out=0,inc=0;C.forEach(j=>{if(j!==v)out+=edges[v+','+j]});C.forEach(i=>{if(i!==v)inc+=edges[i+','+v]});const self=edges[v+','+v];info.innerHTML=`<b>${names[v]}</b> (${v} semitones)<br>Type: ${isPerfect?'Perfect':'Imperfect'}<br><br>Self-loops: <b>${self}</b><br>Outgoing: <b>${out}</b><br>Incoming: <b>${inc}</b><br>Total hom-in: <b>${inc+self}</b><br><br><span style=\"color:#666\">Click elsewhere to deselect</span>`}else{info.innerHTML='Click a node to inspect its voice-leading connections.'}}draw();canvas.addEventListener('click',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;let hit=null;C.forEach(v=>{const p=positions[v];const d=Math.sqrt((mx-p.x)**2+(my-p.y)**2);if(d<30)hit=v});selected=hit===selected?null:hit;draw()});document.getElementById('stats').innerHTML=`Total edges: ${totalEdges} | Vertices: ${C.length} | Density: ${(totalEdges/(C.length*C.length*N)*100).toFixed(1)}% | Missing: ${C.length*C.length*N-totalEdges} (parallel self-loops on perfect consonances)`;</script></body></html>"
    },
    {
      "id": "bottleneck_comparison",
      "title": "The Bottleneck Theorem: Perfect vs Imperfect Consonances",
      "description": "Side-by-side comparison of self-loop counts and incoming voice leadings for perfect versus imperfect consonances. Animated bar chart with the 12:1 ratio.",
      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Bottleneck Theorem</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:30px}.title{font-size:1.4rem;font-weight:300;letter-spacing:2px;margin-bottom:6px;color:#88aaff}.subtitle{font-size:.85rem;color:#666;margin-bottom:30px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:40px;max-width:800px;width:100%}.panel{background:rgba(15,15,35,.8);border:1px solid #223;border-radius:12px;padding:24px}.panel h3{font-size:1rem;font-weight:400;margin-bottom:16px;text-align:center}.bar-container{display:flex;flex-direction:column;gap:10px}.bar-row{display:flex;align-items:center;gap:10px}.bar-label{width:80px;font-size:.75rem;text-align:right;color:#aaa}.bar-track{flex:1;height:28px;background:rgba(255,255,255,.03);border-radius:4px;overflow:hidden;position:relative}.bar-fill{height:100%;border-radius:4px;transition:width 1.5s cubic-bezier(.22,1,.36,1);display:flex;align-items:center;justify-content:flex-end;padding-right:8px;font-size:.75rem;font-weight:600}.bar-val{position:absolute;right:8px;top:50%;transform:translateY(-50%);font-size:.75rem;font-weight:600;color:#fff}.divider{grid-column:1/-1;text-align:center;padding:16px;font-size:1.1rem;color:#88aaff;border-top:1px solid #223;border-bottom:1px solid #223;margin:0 -10px}.big-number{font-size:3rem;font-weight:200;text-align:center;margin:12px 0}.ratio-label{text-align:center;font-size:.85rem;color:#888}.theorem-box{grid-column:1/-1;background:rgba(80,120,255,.05);border:1px solid rgba(80,120,255,.2);border-radius:8px;padding:16px 20px;font-size:.85rem;line-height:1.7;margin-top:10px}b{color:#fff}</style></head><body><div class=\"title\">THE BOTTLENECK THEOREM</div><div class=\"subtitle\">Why Parallel Fifths Are Forbidden — A Quantitative View</div><div class=\"grid\"><div class=\"panel\"><h3 style=\"color:#ff6b6b\">Perfect Consonances</h3><div class=\"bar-container\" id=\"perfect-bars\"></div><div class=\"big-number\" style=\"color:#ff6b6b\">1</div><div class=\"ratio-label\">self-loop per interval</div></div><div class=\"panel\"><h3 style=\"color:#4ecdc4\">Imperfect Consonances</h3><div class=\"bar-container\" id=\"imperfect-bars\"></div><div class=\"big-number\" style=\"color:#4ecdc4\">12</div><div class=\"ratio-label\">self-loops per interval</div></div><div class=\"divider\">Bottleneck Ratio: <b>1 : 12</b></div><div class=\"panel\"><h3 style=\"color:#ff6b6b\">Total Incoming to Perfect</h3><div class=\"big-number\" style=\"color:#ff6b6b\">61</div><div class=\"ratio-label\">permitted voice leadings from all sources</div></div><div class=\"panel\"><h3 style=\"color:#4ecdc4\">Total Incoming to Imperfect</h3><div class=\"big-number\" style=\"color:#4ecdc4\">72</div><div class=\"ratio-label\">permitted voice leadings from all sources</div></div><div class=\"divider\">Constraint Reduction: <b>15.3%</b> fewer paths to perfect consonances</div><div class=\"theorem-box\"><b>Theorem (Perfect Self-Loop Uniqueness):</b> For any perfect consonance p ∈ {0, 7}, the only permitted voice leading from p to p is the identity (0, 0). All 11 non-trivial parallel motions are forbidden.<br><br><b>Theorem (Imperfect Self-Loops):</b> For any imperfect consonance q ∈ {3, 4, 8, 9}, all 12 voice leadings of the form (k, k) for k ∈ ℤ/12ℤ are permitted — including all parallel motions.</div></div><script>const data=[{label:'Unison (0)',type:'P',self:1,total:61},{label:'P5th (7)',type:'P',self:1,total:61},{label:'min 3rd (3)',type:'I',self:12,total:72},{label:'Maj 3rd (4)',type:'I',self:12,total:72},{label:'min 6th (8)',type:'I',self:12,total:72},{label:'Maj 6th (9)',type:'I',self:12,total:72}];function makeBars(id,items,color){const container=document.getElementById(id);items.forEach((d,i)=>{const row=document.createElement('div');row.className='bar-row';row.innerHTML=`<div class=\"bar-label\">${d.label}</div><div class=\"bar-track\"><div class=\"bar-fill\" id=\"bar-${id}-${i}\" style=\"width:0;background:${color}\"></div><div class=\"bar-val\">${d.self} / ${d.total}</div></div>`;container.appendChild(row)})}const perfect=data.filter(d=>d.type==='P');const imperfect=data.filter(d=>d.type==='I');makeBars('perfect-bars',perfect,'rgba(255,107,107,.7)');makeBars('imperfect-bars',imperfect,'rgba(78,205,196,.7)');setTimeout(()=>{perfect.forEach((d,i)=>{document.getElementById('bar-perfect-bars-'+i).style.width=(d.total/72*100)+'%'});imperfect.forEach((d,i)=>{document.getElementById('bar-imperfect-bars-'+i).style.width=(d.total/72*100)+'%'})},100);</script></body></html>"
    },
    {
      "id": "voice_swap_explorer",
      "title": "Voice-Swap Asymmetry: The Broken Mirror",
      "description": "Interactive visualization of the involution i ↦ −i (mod 12) on all 12 pitch-class intervals, showing which consonances are preserved and which are broken by voice exchange.",
      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Voice-Swap Asymmetry</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:30px}.title{font-size:1.4rem;font-weight:300;letter-spacing:2px;margin-bottom:6px;color:#88aaff}.subtitle{font-size:.85rem;color:#666;margin-bottom:24px}canvas{border-radius:12px;background:#0d0d24;box-shadow:0 0 40px rgba(50,80,180,.15)}.explanation{max-width:650px;margin-top:20px;font-size:.85rem;line-height:1.7;color:#aaa;text-align:center}.highlight{color:#ff6b6b;font-weight:600}.ok{color:#4ecdc4}</style></head><body><div class=\"title\">THE BROKEN MIRROR</div><div class=\"subtitle\">Voice-Swap Involution σ(i) = −i mod 12</div><canvas id=\"c\" width=\"650\" height=\"650\"></canvas><div class=\"explanation\">The outer ring shows all 12 pitch-class intervals. <span class=\"ok\">Green</span> intervals are consonant; gray are dissonant. Lines connect each interval i to its mirror σ(i) = −i mod 12. <span class=\"ok\">Green lines</span> preserve consonance. The <span class=\"highlight\">red line</span> from the perfect fifth (7) to the perfect fourth (5) is the unique break — the only consonant interval whose mirror is dissonant.</div><script>const canvas=document.getElementById('c'),ctx=canvas.getContext('2d');const W=650,H=650,cx=W/2,cy=H/2,R=240;const C=new Set([0,3,4,7,8,9]);const names=['Unison','m2','M2','m3','M3','P4','Tritone','P5','m6','M6','m7','M7'];const fullNames=['Unison (0)','Minor 2nd (1)','Major 2nd (2)','Minor 3rd (3)','Major 3rd (4)','Perfect 4th (5)','Tritone (6)','Perfect 5th (7)','Minor 6th (8)','Major 6th (9)','Minor 7th (10)','Major 7th (11)'];function pos(i){const a=-Math.PI/2+i*Math.PI*2/12;return{x:cx+R*Math.cos(a),y:cy+R*Math.sin(a)}}function neg(i){return(12-i)%12}let hovered=-1;function draw(){ctx.clearRect(0,0,W,H);for(let i=0;i<12;i++){const j=neg(i);if(j<=i)continue;const p1=pos(i),p2=pos(j);const iCons=C.has(i),jCons=C.has(j);let color,width;if(iCons&&!jCons){color='rgba(255,107,107,.6)';width=3}else if(!iCons&&jCons){color='rgba(255,107,107,.6)';width=3}else if(iCons&&jCons){color='rgba(78,205,196,.25)';width=1.5}else{color='rgba(100,100,130,.1)';width=.5}if(hovered===i||hovered===j){width*=2;color=color.replace(/[\\d.]+\\)$/,'.9)')}ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}for(let i=0;i<6;i++){if(neg(i)===i){const p=pos(i);ctx.beginPath();ctx.arc(p.x,p.y,35,0,Math.PI*2);ctx.strokeStyle=C.has(i)?'rgba(78,205,196,.3)':'rgba(100,100,130,.15)';ctx.lineWidth=1;ctx.setLineDash([3,3]);ctx.stroke();ctx.setLineDash([])}}for(let i=0;i<12;i++){const p=pos(i);const isCons=C.has(i);const r=isCons?20:14;const isPerfect=i===0||i===7;if(isCons){ctx.beginPath();ctx.arc(p.x,p.y,r+8,0,Math.PI*2);ctx.fillStyle=isPerfect?'rgba(255,107,107,.08)':'rgba(78,205,196,.08)';ctx.fill()}ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);if(isCons){ctx.fillStyle=isPerfect?'#ff6b6b':'#4ecdc4';if(hovered===i)ctx.fillStyle=isPerfect?'#ff9b9b':'#7eeee7'}else{ctx.fillStyle=hovered===i?'#556':'#334'}ctx.fill();ctx.strokeStyle=hovered===i?'#fff':'rgba(255,255,255,.2)';ctx.lineWidth=hovered===i?2:1;ctx.stroke();ctx.fillStyle=isCons?'#fff':'#888';ctx.font=`${isCons?'bold ':' '}${isCons?11:9}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(names[i],p.x,p.y);const lp={x:cx+(R+35)*Math.cos(-Math.PI/2+i*Math.PI*2/12),y:cy+(R+35)*Math.sin(-Math.PI/2+i*Math.PI*2/12)};ctx.fillStyle='#666';ctx.font='9px system-ui';ctx.fillText(i+'',lp.x,lp.y)}ctx.fillStyle='#fff';ctx.font='13px system-ui';ctx.textAlign='center';ctx.fillText('σ(i) = −i mod 12',cx,cy-20);ctx.fillStyle='#888';ctx.font='11px system-ui';ctx.fillText('Voice Exchange Involution',cx,cy+5);if(hovered>=0){const j=neg(hovered);const hC=C.has(hovered),jC=C.has(j);ctx.fillStyle='#fff';ctx.font='12px system-ui';ctx.fillText(`${fullNames[hovered]}  →  ${fullNames[j]}`,cx,cy+35);ctx.fillStyle=hC===jC?'#4ecdc4':'#ff6b6b';ctx.fillText(hC===jC?'✓ Consonance preserved':'✗ Consonance BROKEN',cx,cy+55)}}draw();canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;hovered=-1;for(let i=0;i<12;i++){const p=pos(i);if(Math.sqrt((mx-p.x)**2+(my-p.y)**2)<25){hovered=i;break}}draw()});canvas.addEventListener('mouseleave',()=>{hovered=-1;draw()});</script></body></html>"
    }
  ]
