theorem bch_defect_zero_of_commute (h₁ h₂ : 𝔸) (hcomm : Commute h₁ h₂) :
    bchDefect h₁ h₂ = 0 := by
  simp [bchDefect, NormedSpace.exp_add_of_commute hcomm]

/-- **Self-Inverse Defect**: bchDefect(h, -h) = 0. -/

theorem qeml_channel_compose_comm (h₁ h₂ : 𝔸) (hcomm : Commute h₁ h₂) (ρ : 𝔸) :
    qemlChannel h₁ (qemlChannel h₂ ρ) = qemlChannel (h₁ + h₂) ρ := by
  have h_split_exp : NormedSpace.exp (h₁ + h₂) = NormedSpace.exp h₁ * NormedSpace.exp h₂ := by
    exact?;
  have h_split_exp_neg : NormedSpace.exp (-(h₁ + h₂)) = NormedSpace.exp (-h₂) * NormedSpace.exp (-h₁) := by
    have := NormedSpace.exp_add_of_commute ( show Commute ( -h₂ ) ( -h₁ ) from by simp [ hcomm.symm ] ) ; simp_all +decide [ ← mul_assoc ] ;
  unfold qemlChannel; simp_all +decide [ mul_assoc ] ;

