/-- **Neuron at Zero**: qemlNeuron 0 t ρ = ρ + t • 1. -/

theorem qeml_dist_triangle (g₁ g₂ g₃ : QuantumEMLGate 𝔸) :
    qemlDist g₁ g₃ ≤ qemlDist g₁ g₂ + qemlDist g₂ g₃ := by
