r/32)*cellH;if(!alive[r]){ctx.fillStyle='#1a1a2e';ctx.fillRect(x,y,cellW-1,cellH-1)}else{let hue=120+r*0.5;ctx.fillStyle='hsl('+hue+',70%,50%)';ctx.fillRect(x,y,cellW-1,cellH-1);ctx.fillStyle='white';ctx.font='9px monospace';ctx.fillText(r,x+2,y+cellH-3)}}ctx.fillStyle='#e94560';ctx.font='14px Arial';let count=alive.filter(a=>a).length;ctx.fillText('Period ≤ '+(step>0?periods[step-1]:'—')+': '+count+' rules survive',10,canvas.height-5)}function runStep(){if(step>=periods.length){surv.innerHTML='<b>Survivors:</b> '+alive.map((a,i)=>a?i:null).filter(x=>x!==null).join(', ');status.textContent='✅ Sieve complete!';return}let p=periods[step];for(let r=0;r<256;r++){if(alive[r]&&!isRev(r,p))alive[r]=false}step++;drawGrid();let count=alive.filter(a=>a).length;status.textContent='After period '+p+': '+count+' rules';setTimeout(runStep,800)}btn.addEventListener('click',function(){alive=new Array(256).fill(true);step=0;status.textContent='Running...';surv.innerHTML='';drawGrid();setTimeout(runStep,500)});drawGrid()})();</script>"
