awLattice(selected){svg.innerHTML='';for(let[a,b]of edges){let sa=subgroups[a],sb=subgroups[b];let line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',170);line.setAttribute('y1',sa.y+15);line.setAttribute('x2',a===0&&b===1?100:a===0&&b===2?240:b===4?170:a===1?100:240);line.setAttribute('y2',sb.y+15);line.setAttribute('stroke','rgba(255,255,255,0.3)');line.setAttribute('stroke-width','2');svg.appendChild(line)}subgroups.forEach((s,i)=>{let x=i===0?170:i===1?100:i===2?240:i===3?170:170;let g=document.createElementNS('http://www.w3.org/2000/svg','g');g.style.cursor='pointer';g.onclick=()=>showFixed(i);let rect=document.createElementNS('http://www.w3.org/2000/svg','rect');rect.setAttribute('x',x-50);rect.setAttribute('y',s.y);rect.setAttribute('width',100);rect.setAttribute('height',30);rect.setAttribute('rx',5);rect.setAttribute('fill',i===selected?'white':s.color);rect.setAttribute('stroke','white');rect.setAttribute('stroke-width',i===selected?'3':'1');g.appendChild(rect);let text=document.createElementNS('http://www.w3.org/2000/svg','text');text.setAttribute('x',x);text.setAttribute('y',s.y+20);text.setAttribute('text-anchor','middle');text.setAttribute('fill',i===selected?s.color:'white');text.setAttribute('font-size','13');text.setAttribute('font-weight','bold');text.textContent=s.name;g.appendChild(text);svg.appendChild(g)})}function showFixed(idx){let s=subgroups[idx];let fixed=configs.filter(c=>isFixed(c,s.generators));drawLattice(idx);fixedInfo.innerHTML='<b>'+s.name+'</b> (order '+s.order+')<br>Fixes <b>'+fixed.length+'</b> out of 8 configurations:<br>';let html='';for(let c of fixed){html+='<span style=\"display:inline-block;margin:3px;padding:3px 8px;background:rgba(255,255,255,0.2);border-radius:4px;font-family:monospace\">'+c.join('')+'</span> '}fixedInfo.innerHTML+=html;configGrid.innerHTML='<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:5px\">';for(let c of configs){let isF=fixed.s