or:#888;text-align:center\">(Grid too large to display — try A=2, L=2)</p>';document.getElementById('volCount').textContent=nVol;document.getElementById('selfCount').textContent=nSelf>1e15?A+'^('+L+'·'+A+'^'+L+')':nSelf.toLocaleString();document.getElementById('explText').textContent=`With A=${A}, L=${L}: ${nVol} volumes but ${nSelf>1e15?'A^(L·A^L)':nSelf.toLocaleString()} self-evaluations. The catalog cannot exist.`;return}const vols=[];function genVols(prefix){if(prefix.length===L){vols.push([...prefix]);return}for(let a=0;a<A;a++){prefix.push(a);genVols(prefix);prefix.pop()}}genVols([]);const colors=['#2a5a8c','#8c2a5a','#5a8c2a','#8c5a2a','#2a8c5a','#5a2a8c','#8c8c2a','#2a8c8c','#8c2a8c'];let html='<div class=\"grid\" style=\"grid-template-columns:60px repeat('+nVol+',28px)\">';html+='<div class=\"row-label\"></div>';for(let j=0;j<nVol;j++){html+=`<div class=\"col-label\">v${j}</div>`}for(let i=0;i<nVol;i++){html+=`<div class=\"row-label\">φ(v${i})=</div>`;for(let j=0;j<nVol;j++){const val=vols[(i*3+j*7+i*j)%nVol][j%L];const isDiag=i===j;const bg=isDiag?'#6b2a2a':'#1a1a2e';const border=isDiag?'2px solid #ff6b6b':'1px solid #333';html+=`<div class=\"grid-cell\" style=\"background:${bg};border:${border}\">${val}</div>`}}html+='</div>';html+='<p style=\"font-size:.85em;color:#ff6b6b;text-align:center;margin-top:10px\">Diagonal values: shift each by +1 mod '+A+' → a function that differs from every row.</p>';container.innerHTML=html;document.getElementById('volCount').textContent=nVol;document.getElementById('selfCount').textContent=nSelf>1e6?A+'^('+L+'·'+nVol+')':nSelf;document.getElementById('explText').textContent=`A=${A}, L=${L}: ${nVol} volumes vs ${nSelf>1e6?'A^(L·A^L) = '+A+'^'+(L*nVol):nSelf} self-evaluations. Ratio: ${nSelf>1e6?'astronomically large':(nSelf/nVol).toFixed(0)+'×'}.`}document.getElementById('pA').onchange=render;document.getElementById('pL').onchange=render;render()</script></body></html>"
