ntervals[j].v);edges.push({from:i,to:j,count:cnt})}const positions=intervals.map((_,i)=>{let a=-Math.PI/2+i*2*Math.PI/6;return{x:cx+R*Math.cos(a),y:cy+R*Math.sin(a)}});let selected=-1;function draw(){ctx.clearRect(0,0,W,H);edges.forEach(e=>{if(e.from===e.to)return;let p1=positions[e.from],p2=positions[e.to];let dx=p2.x-p1.x,dy=p2.y-p1.y,len=Math.sqrt(dx*dx+dy*dy);let nx=-dy/len,ny=dx/len;let off=8;let mx=(p1.x+p2.x)/2+nx*off*2,my=(p1.y+p2.y)/2+ny*off*2;let alpha=0.15,lw=Math.max(1,e.count/4);if(selected>=0){if(e.from===selected){alpha=0.9;lw=Math.max(2,e.count/3)}else if(e.to===selected){alpha=0.6;lw=Math.max(1.5,e.count/3.5)}else{alpha=0.05}}ctx.beginPath();ctx.moveTo(p1.x+nx*off,p1.y+ny*off);ctx.quadraticCurveTo(mx,my,p2.x+nx*off,p2.y+ny*off);ctx.strokeStyle=`rgba(100,180,255,${alpha})`;ctx.lineWidth=lw;ctx.stroke();if(alpha>0.1){let t=0.7,bx=(1-t)*(1-t)*(p1.x+nx*off)+2*(1-t)*t*mx+t*t*(p2.x+nx*off),by=(1-t)*(1-t)*(p1.y+ny*off)+2*(1-t)*t*my+t*t*(p2.y+ny*off);let t2=0.71,bx2=(1-t2)*(1-t2)*(p1.x+nx*off)+2*(1-t2)*t2*mx+t2*t2*(p2.x+nx*off),by2=(1-t2)*(1-t2)*(p1.y+ny*off)+2*(1-t2)*t2*my+t2*t2*(p2.y+ny*off);let adx=bx2-bx,ady=by2-by,al=Math.sqrt(adx*adx+ady*ady)||1;adx/=al;ady/=al;ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(bx-adx*8-ady*4,by-ady*8+adx*4);ctx.lineTo(bx-adx*8+ady*4,by-ady*8-adx*4);ctx.closePath();ctx.fillStyle=`rgba(100,180,255,${alpha})`;ctx.fill()}if(selected===e.from&&alpha>0.3){ctx.font='11px monospace';ctx.fillStyle=`rgba(255,255,255,${alpha*0.8})`;ctx.fillText(e.count,(p1.x+p2.x)/2+nx*20,(p1.y+p2.y)/2+ny*20)}});edges.forEach(e=>{if(e.from!==e.to)return;let p=positions[e.from];let a=-Math.PI/2+e.from*2*Math.PI/6;let lr=25,lx=p.x+Math.cos(a)*lr,ly=p.y+Math.sin(a)*lr;let alpha=0.2;if(selected===e.from)alpha=0.9;else if(selected>=0)alpha=0.05;ctx.beginPath();ctx.arc(lx,ly,15,0,Math.PI*2);ctx.strokeStyle=`rgba(255,200,100,${alpha})`;ctx.lineWidth=Math.max(1,e.count/4);ctx.stroke();if(selected===e.from){ctx.font='bold 11px monospace';ctx.fillStyle=`rgba(255,200,100,${alpha})`;ctx.textAlign='center';ctx.fillText(e.count,lx+Math.cos(a)*20,ly+Math.sin(a)*20)}});intervals.forEach((intv,i)=>{let p=positions[i];let col=intv.perfect?'#ff6b6b':'#4ecdc4';let r=selected===i?30:24;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fillStyle=selected===i?col:(col+'44');ctx.fill();ctx.strokeStyle=col;ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 13px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(intv.v,p.x,p.y);ctx.font='11px sans-serif';ctx.fillStyle='#ccc';ctx.fillText(intv.name,p.x,p.y+r+14)})}C.addEventListener('click',e=>{let rect=C.getBoundingClientRect(),mx=e.clientX-rect.left,my=e.clientY-rect.top;let clicked=-1;positions.forEach((p,i)=>{if(Math.hypot(p.x-mx,p.y-my)<30)clicked=i});if(clicked===selected)selected=-1;else selected=clicked;draw();let info=document.getElementById('info');if(selected>=0){let intv=intervals[selected];let outgoing=edges.filter(e=>e.from===selected).reduce((s,e)=>s+e.count,0);let incoming=edges.filter(e=>e.to===selected).reduce((s,e)=>s+e.count,0);let self=edges.find(e=>e.from===selected&&e.to===selected).count;info.innerHTML=`<b>${intv.name}</b> (interval ${intv.v}) — ${intv.perfect?'Perfect':'Imperfect'} consonance<br>Outgoing: ${outgoing} | Incoming: ${incoming} | Self-loops: ${self}`}else{info.textContent='Click a node to explore its voice-leading connections'}});draw()</script></body></html>"
