>Length: <select id='hL'><option value='3'>3</option><option value='4' selected>4</option><option value='5'>5</option></select></label></div><div class='legend'><span style='color:#888'>Distance:</span><span>0</span><div class='legend-item' style='background:#001'></div><div class='legend-item' style='background:#124'></div><div class='legend-item' style='background:#247'></div><div class='legend-item' style='background:#48a'></div><div class='legend-item' style='background:#6bd'></div><div class='legend-item' style='background:#f92'></div><span>L</span></div><canvas id='heatmap'></canvas><div class='info' id='hoverInfo'>Hover over the heatmap to see distances</div><div class='dist-hist'><h3>Distance Distribution (all pairs)</h3><div id='histBars'></div></div></div><script>let volumes=[];function genVolumes(A,L){const n=Math.pow(A,L);const vols=[];for(let v=0;v<n;v++){const s=[];let x=v;for(let i=0;i<L;i++){s.push(x%A);x=Math.floor(x/A)}vols.push(s)}return vols}function hDist(a,b){let d=0;for(let i=0;i<a.length;i++)if(a[i]!==b[i])d++;return d}function color(d,maxD){if(d===0)return'rgb(0,5,15)';const t=d/maxD;const r=Math.floor(40+200*Math.pow(t,1.5));const g=Math.floor(80+100*t-60*t*t);const b2=Math.floor(180-80*t);return'rgb('+r+','+g+','+b2+')'}function draw(){const A=parseInt(document.getElementById('hA').value);const L=parseInt(document.getElementById('hL').value);volumes=genVolumes(A,L);const n=volumes.length;const canvas=document.getElementById('heatmap');const size=Math.min(700,Math.max(300,n*4));canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');const cell=size/n;const distCount=Array(L+1).fill(0);for(let i=0;i<n;i++){for(let j=0;j<n;j++){const d=hDist(volumes[i],volumes[j]);if(j>=i)distCount[d]++;ctx.fillStyle=color(d,L);ctx.fillRect(j*cell,i*cell,Math.ceil(cell),Math.ceil(cell))}}const maxC=Math.max(...distCount);const hist=document.getElementById('histBars');hist.innerHTML='';for(let d=0;d<=L;d++){const row=document.createElement('div'